-- Crumble POS: full database setup for a NEW Supabase project.
-- Generated by supabase/bundle.sh from supabase/migrations. Do not edit.
-- Paste the whole file into SQL Editor and run it once. Everything runs in
-- one transaction: on any error nothing is applied.

begin;

-- ===== 20261027000001_schema.sql =====
-- Crumble POS cloud schema (see CRUMBLE_POS_PLAN.md §8).
--
-- * Every id is a UUID generated on the POS, so there is no server default.
-- * Money is integer kuruş. Timestamps are timestamptz (UTC).
-- * created_at / updated_at come from the POS; updated_at drives
--   last-writer-wins for the catalog, so the server does not overwrite it.

-- ---------------------------------------------------------------------------
-- Catalog
-- ---------------------------------------------------------------------------

create table public.categories (
  id uuid primary key,
  name text not null check (btrim(name) <> ''),
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

create table public.products (
  id uuid primary key,
  category_id uuid not null references public.categories (id),
  name text not null check (btrim(name) <> ''),
  description text,
  price integer not null check (price >= 0),
  is_active boolean not null default true,
  needs_price_check boolean not null default false,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

create index products_category_id_idx on public.products (category_id);

create table public.floor_plans (
  id uuid primary key,
  name text not null check (btrim(name) <> ''),
  sort_order integer not null default 0,
  background_image_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

create table public.tables (
  id uuid primary key,
  floor_plan_id uuid not null references public.floor_plans (id),
  label text not null,
  shape text not null check (shape in ('circle', 'square', 'rectangle', 'rounded_rectangle')),
  x double precision not null,
  y double precision not null,
  width double precision not null check (width > 0),
  height double precision not null check (height > 0),
  rotation double precision not null default 0,
  color text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

create index tables_floor_plan_id_idx on public.tables (floor_plan_id);

-- ---------------------------------------------------------------------------
-- Shifts, tabs and money movements
-- ---------------------------------------------------------------------------

create table public.shifts (
  id uuid primary key,
  opened_at timestamptz not null,
  closed_at timestamptz,
  opening_cash integer not null check (opening_cash >= 0),
  counted_cash integer check (counted_cash >= 0),
  expected_cash integer,
  cash_difference integer,
  notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- Closing fills all close fields at once.
  constraint shifts_close_fields check (
    (closed_at is null and counted_cash is null and expected_cash is null and cash_difference is null)
    or (closed_at is not null and counted_cash is not null and expected_cash is not null
        and cash_difference is not null and cash_difference = counted_cash - expected_cash)
  ),
  constraint shifts_closed_after_opened check (closed_at is null or closed_at >= opened_at)
);

-- Only one open shift at a time.
create unique index shifts_single_open_idx on public.shifts ((true)) where closed_at is null;

create table public.tabs (
  id uuid primary key,
  opened_shift_id uuid not null references public.shifts (id),
  closed_shift_id uuid references public.shifts (id),
  kind text not null check (kind in ('quick', 'table', 'named')),
  table_id uuid references public.tables (id),
  customer_name text check (customer_name is null or btrim(customer_name) <> ''),
  status text not null default 'open' check (status in ('open', 'paid', 'void')),
  -- Cart discount, whole percent only (presets 10/15 or typed).
  discount_percent integer check (discount_percent between 1 and 100),
  total integer check (total >= 0),
  opened_at timestamptz not null,
  closed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint tabs_kind_fields check (
    (kind <> 'table' or table_id is not null)
    and (kind <> 'named' or customer_name is not null)
  ),
  -- open: nothing closed yet. paid/void: closed in a shift. paid: total frozen.
  constraint tabs_status_fields check (
    (status = 'open' and closed_at is null and closed_shift_id is null and total is null)
    or (status = 'paid' and closed_at is not null and closed_shift_id is not null and total is not null)
    or (status = 'void' and closed_at is not null and closed_shift_id is not null)
  )
);

create index tabs_opened_shift_id_idx on public.tabs (opened_shift_id);
create index tabs_closed_shift_id_idx on public.tabs (closed_shift_id);
create index tabs_open_idx on public.tabs (status) where status = 'open';

create table public.tab_items (
  id uuid primary key,
  tab_id uuid not null references public.tabs (id),
  -- Kept after the product is soft-deleted or merged into a variant later.
  product_id uuid not null references public.products (id),
  name_snapshot text not null,
  -- Menu price when the line was added. unit_price is what was charged;
  -- they differ when the cashier used "Fiyatı değiştir".
  list_price integer not null check (list_price >= 0),
  unit_price integer not null check (unit_price >= 0),
  quantity integer not null check (quantity > 0),
  discount_percent integer check (discount_percent between 1 and 100),
  is_comp boolean not null default false,
  note text,
  voided_at timestamptz,
  void_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- Lets refunds reference (tab_item_id, tab_id) so an item refund always
  -- belongs to the same tab.
  constraint tab_items_id_tab_id_key unique (id, tab_id),
  constraint tab_items_void_reason check (void_reason is null or voided_at is not null)
);

create index tab_items_tab_id_idx on public.tab_items (tab_id);
create index tab_items_product_id_idx on public.tab_items (product_id);

create table public.payments (
  id uuid primary key,
  tab_id uuid not null references public.tabs (id),
  -- The shift the money was taken in, not the shift the tab was opened in.
  shift_id uuid not null references public.shifts (id),
  method text not null check (method in ('cash', 'card')),
  amount integer not null check (amount > 0),
  paid_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index payments_tab_id_idx on public.payments (tab_id);
create index payments_shift_id_idx on public.payments (shift_id);

create table public.refunds (
  id uuid primary key,
  tab_id uuid not null references public.tabs (id),
  tab_item_id uuid,
  -- The shift the refund was given in.
  shift_id uuid not null references public.shifts (id),
  amount integer not null check (amount > 0),
  method text not null check (method in ('cash', 'card')),
  reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint refunds_tab_item_fk foreign key (tab_item_id, tab_id)
    references public.tab_items (id, tab_id)
);

create index refunds_tab_id_idx on public.refunds (tab_id);
create index refunds_shift_id_idx on public.refunds (shift_id);

-- ---------------------------------------------------------------------------
-- History and people
-- ---------------------------------------------------------------------------

-- No user column on purpose: the POS has one shared login (plan §2).
create table public.catalog_changes (
  id uuid primary key,
  entity_type text not null check (entity_type in ('product', 'category', 'table', 'floor_plan')),
  entity_id uuid not null,
  action text not null check (action in ('create', 'update', 'delete')),
  field text,
  old_value text,
  new_value text,
  changed_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index catalog_changes_changed_at_idx on public.catalog_changes (changed_at desc);
create index catalog_changes_entity_idx on public.catalog_changes (entity_type, entity_id);

-- Partners (owners) who may use the manager app. Employees are never listed.
create table public.partners (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null unique references auth.users (id),
  email text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ===== 20261027000002_immutability.sql =====
-- Immutability rules (CRUMBLE_POS_PLAN.md §4), enforced by the database so a
-- buggy client or a bad sync can never rewrite history.
--
-- * Nothing is ever physically deleted (catalog uses deleted_at).
-- * payments, refunds and catalog_changes are insert-only.
-- * tabs, tab_items and shifts may only change their lifecycle fields, and
--   only while they are still open.
--
-- A no-op update (new row identical to the old one) is always allowed so that
-- a re-sent sync upsert stays idempotent.

create schema if not exists private;

-- True when old and new differ only in the given columns.
create function private.changes_only(old_row jsonb, new_row jsonb, allowed text[])
returns boolean
language sql
immutable
set search_path = ''
as $$
  select (old_row - allowed) = (new_row - allowed);
$$;

create function private.reject_delete()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'Kayıt silinemez (%). Katalog için deleted_at kullanın.', tg_table_name
    using errcode = 'restrict_violation';
end;
$$;

create function private.reject_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if to_jsonb(new) = to_jsonb(old) then
    return new;
  end if;
  raise exception 'Kayıt değiştirilemez (%). Düzeltme için iade kaydı ekleyin.', tg_table_name
    using errcode = 'restrict_violation';
end;
$$;

create function private.guard_tab_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if to_jsonb(new) = to_jsonb(old) then
    return new;
  end if;
  if old.status <> 'open' then
    raise exception 'Kapanmış hesap değiştirilemez (tab %).', old.id
      using errcode = 'restrict_violation';
  end if;
  if not private.changes_only(to_jsonb(old), to_jsonb(new), array[
    'status', 'closed_at', 'closed_shift_id', 'total', 'table_id', 'customer_name',
    'discount_percent', 'updated_at'
  ]) then
    raise exception 'Hesapta sadece yaşam döngüsü alanları değiştirilebilir (tab %).', old.id
      using errcode = 'restrict_violation';
  end if;
  return new;
end;
$$;

create function private.guard_tab_item_insert()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- Re-sent insert of an existing row: let ON CONFLICT handle it.
  if exists (select 1 from public.tab_items where id = new.id) then
    return new;
  end if;
  if (select status from public.tabs where id = new.tab_id) <> 'open' then
    raise exception 'Kapanmış hesaba kalem eklenemez (tab %).', new.tab_id
      using errcode = 'restrict_violation';
  end if;
  return new;
end;
$$;

create function private.guard_tab_item_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if to_jsonb(new) = to_jsonb(old) then
    return new;
  end if;
  if (select status from public.tabs where id = old.tab_id) <> 'open' then
    raise exception 'Kapanmış hesabın kalemi değiştirilemez (tab_item %).', old.id
      using errcode = 'restrict_violation';
  end if;
  if old.voided_at is not null then
    raise exception 'İptal edilmiş kalem değiştirilemez (tab_item %).', old.id
      using errcode = 'restrict_violation';
  end if;
  if not private.changes_only(to_jsonb(old), to_jsonb(new), array[
    'quantity', 'unit_price', 'discount_percent', 'is_comp', 'note',
    'voided_at', 'void_reason', 'updated_at'
  ]) then
    raise exception 'Kalemde sadece yaşam döngüsü alanları değiştirilebilir (tab_item %).', old.id
      using errcode = 'restrict_violation';
  end if;
  return new;
end;
$$;

create function private.guard_shift_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if to_jsonb(new) = to_jsonb(old) then
    return new;
  end if;
  if old.closed_at is not null then
    raise exception 'Kapanmış vardiya değiştirilemez (shift %).', old.id
      using errcode = 'restrict_violation';
  end if;
  if not private.changes_only(to_jsonb(old), to_jsonb(new), array[
    'closed_at', 'counted_cash', 'expected_cash', 'cash_difference', 'notes', 'updated_at'
  ]) then
    raise exception 'Vardiyada sadece kapanış alanları değiştirilebilir (shift %).', old.id
      using errcode = 'restrict_violation';
  end if;
  return new;
end;
$$;

-- No physical deletes anywhere (row and TRUNCATE).
do $$
declare
  t text;
begin
  foreach t in array array[
    'categories', 'products', 'floor_plans', 'tables', 'shifts', 'tabs', 'tab_items',
    'payments', 'refunds', 'catalog_changes', 'partners'
  ] loop
    execute format(
      'create trigger %I before delete on public.%I for each row execute function private.reject_delete()',
      t || '_no_delete', t);
    execute format(
      'create trigger %I before truncate on public.%I for each statement execute function private.reject_delete()',
      t || '_no_truncate', t);
  end loop;
end;
$$;

-- Insert-only tables.
create trigger payments_no_update before update on public.payments
  for each row execute function private.reject_update();
create trigger refunds_no_update before update on public.refunds
  for each row execute function private.reject_update();
create trigger catalog_changes_no_update before update on public.catalog_changes
  for each row execute function private.reject_update();

-- Lifecycle-only tables.
create trigger tabs_guard_update before update on public.tabs
  for each row execute function private.guard_tab_update();
create trigger tab_items_guard_insert before insert on public.tab_items
  for each row execute function private.guard_tab_item_insert();
create trigger tab_items_guard_update before update on public.tab_items
  for each row execute function private.guard_tab_item_update();
create trigger shifts_guard_update before update on public.shifts
  for each row execute function private.guard_shift_update();

-- ===== 20261027000003_rls.sql =====
-- Row Level Security (CRUMBLE_POS_PLAN.md §7).
--
-- * device  : the single POS PC. A Supabase Auth user whose
--             app_metadata.role = 'device' (only an admin / service role can
--             set app_metadata). Inserts and updates; updates are further
--             limited by the immutability triggers. Never deletes.
-- * partner : a user listed in public.partners. Read-only, all tables.
-- * anyone else (anon, employees, unknown users): nothing.
--
-- The service role key bypasses RLS and must never be shipped in a client.

create function private.is_device()
returns boolean
language sql
stable
set search_path = ''
as $$
  select coalesce(auth.jwt() -> 'app_metadata' ->> 'role', '') = 'device';
$$;

-- security definer so the lookup is not itself subject to partners' RLS.
create function private.is_partner()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.partners where user_id = auth.uid());
$$;

grant usage on schema private to authenticated;
grant execute on function private.is_device() to authenticated;
grant execute on function private.is_partner() to authenticated;
revoke execute on function private.is_device() from public, anon;
revoke execute on function private.is_partner() from public, anon;

do $$
declare
  t text;
begin
  -- Tables the device writes. Partners read everything.
  foreach t in array array[
    'categories', 'products', 'floor_plans', 'tables', 'shifts', 'tabs', 'tab_items',
    'payments', 'refunds', 'catalog_changes'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('revoke delete, truncate on public.%I from authenticated', t);

    execute format(
      'create policy %I on public.%I for select to authenticated using (private.is_device() or private.is_partner())',
      t || '_select', t);
    execute format(
      'create policy %I on public.%I for insert to authenticated with check (private.is_device())',
      t || '_device_insert', t);
  end loop;

  -- Tables with updatable (lifecycle / catalog) fields. payments, refunds and
  -- catalog_changes get no update policy at all.
  foreach t in array array[
    'categories', 'products', 'floor_plans', 'tables', 'shifts', 'tabs', 'tab_items'
  ] loop
    execute format(
      'create policy %I on public.%I for update to authenticated using (private.is_device()) with check (private.is_device())',
      t || '_device_update', t);
  end loop;

  foreach t in array array['payments', 'refunds', 'catalog_changes'] loop
    execute format('revoke update on public.%I from authenticated', t);
  end loop;
end;
$$;

-- partners: read-only for partners, managed by an admin only.
alter table public.partners enable row level security;
revoke all on public.partners from anon;
revoke insert, update, delete, truncate on public.partners from authenticated;
create policy partners_select on public.partners
  for select to authenticated using (private.is_partner());

-- ===== 20261028000004_void_rule.sql =====
-- A tab that took money can only be voided after it is refunded
-- (CRUMBLE_POS_PLAN.md §5.5). Mirrors the local SQLite trigger.

create function private.guard_tab_void()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'void' and old.status = 'open'
    and coalesce((select sum(amount) from public.payments where tab_id = new.id), 0)
      <> coalesce((select sum(amount) from public.refunds where tab_id = new.id), 0) then
    raise exception 'Ödemesi alınmış hesap iptal edilemez. Önce iade yapın (tab %).', new.id
      using errcode = 'restrict_violation';
  end if;
  return new;
end;
$$;

create trigger tabs_guard_void before update on public.tabs
  for each row execute function private.guard_tab_void();

-- ===== 20261028000005_device_status.sql =====
-- When the POS last synced (plan §6: the manager app shows "son senkron: HH:MM").
-- One row, written by the device after each successful push.

create table public.device_status (
  id text primary key,
  last_sync_at timestamptz not null,
  pending integer not null default 0 check (pending >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.device_status enable row level security;
revoke all on public.device_status from anon;
revoke delete, truncate on public.device_status from authenticated;

create policy device_status_select on public.device_status
  for select to authenticated using (private.is_device() or private.is_partner());
create policy device_status_device_insert on public.device_status
  for insert to authenticated with check (private.is_device());
create policy device_status_device_update on public.device_status
  for update to authenticated using (private.is_device()) with check (private.is_device());

-- ===== 20261028000006_realtime.sql =====
-- Manager app (plan §6): live updates via Supabase Realtime. RLS still
-- applies to what each subscriber receives.
alter publication supabase_realtime add table
  public.tabs, public.payments, public.refunds, public.shifts, public.device_status;

-- Reports select shifts by opening time (report day = shift opening day).
create index shifts_opened_at_idx on public.shifts (opened_at);

-- ===== 20261029000007_shift_without_count.sql =====
-- Kasa sayımı kaldırıldı (CRUMBLE_POS_PLAN.md §5.4, 2026-10-29): a shift can
-- close without a counted cash amount. Closing still fills closed_at and
-- expected_cash; counted_cash and cash_difference are either both empty or
-- both filled (older shifts closed with a count stay valid).
alter table public.shifts drop constraint shifts_close_fields;
alter table public.shifts add constraint shifts_close_fields check (
  (closed_at is null and counted_cash is null and expected_cash is null and cash_difference is null)
  or (closed_at is not null and expected_cash is not null
      and ((counted_cash is null and cash_difference is null)
           or (counted_cash is not null and cash_difference is not null
               and cash_difference = counted_cash - expected_cash)))
);

-- ===== 20261030000008_mobile_menu.sql =====
-- Telefondan menü (CRUMBLE_POS_PLAN.md §6, 2026-10-30): partners may change a
-- product's price, add a product and delete one (soft). This is the only
-- write the manager app does. It goes through these functions, so a partner
-- can touch nothing else; each change is logged with source = 'mobile'. The
-- POS pulls newer products back (last writer wins on updated_at).

alter table public.catalog_changes
  add column source text not null default 'pos' check (source in ('pos', 'mobile'));

-- Last writer wins for products: an upsert carrying an older updated_at (e.g.
-- an old POS change still in its outbox) does not overwrite a newer row.
create function private.products_last_writer_wins()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.updated_at < old.updated_at then
    return null;
  end if;
  return new;
end;
$$;

create trigger products_last_writer_wins before update on public.products
  for each row execute function private.products_last_writer_wins();

create function private.require_partner()
returns void
language plpgsql
set search_path = ''
as $$
begin
  if not private.is_partner() then
    raise exception 'Sadece ortaklar menüyü değiştirebilir.' using errcode = '42501';
  end if;
end;
$$;

create function public.menu_set_price(p_product uuid, p_price integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current public.products%rowtype;
begin
  perform private.require_partner();
  if p_price is null or p_price < 0 then
    raise exception 'Fiyat negatif olamaz.' using errcode = '22023';
  end if;
  select * into current from public.products where id = p_product and deleted_at is null for update;
  if not found then
    raise exception 'Ürün bulunamadı.' using errcode = 'P0002';
  end if;
  if current.price = p_price then
    return;
  end if;
  -- Same rule as the POS: a product imported without a price becomes active
  -- once it gets one; saving a price clears "teyit edilecek".
  update public.products
     set price = p_price,
         needs_price_check = false,
         is_active = case when not current.is_active and current.price = 0 and p_price > 0 then true else current.is_active end,
         updated_at = now()
   where id = p_product;
  insert into public.catalog_changes (id, entity_type, entity_id, action, field, old_value, new_value, changed_at, source)
  values (gen_random_uuid(), 'product', p_product, 'update', 'price', current.price::text, p_price::text, now(), 'mobile');
end;
$$;

create function public.menu_add_product(p_id uuid, p_category uuid, p_name text, p_price integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  clean text := btrim(coalesce(p_name, ''));
begin
  perform private.require_partner();
  if clean = '' then
    raise exception 'Ürün adı boş olamaz.' using errcode = '22023';
  end if;
  if p_price is null or p_price < 0 then
    raise exception 'Fiyat negatif olamaz.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.categories where id = p_category and deleted_at is null) then
    raise exception 'Kategori bulunamadı.' using errcode = 'P0002';
  end if;
  insert into public.products (id, category_id, name, description, price, is_active, needs_price_check, sort_order, created_at, updated_at, deleted_at)
  values (
    p_id, p_category, clean, null, p_price, true, false,
    coalesce((select max(sort_order) + 1 from public.products where category_id = p_category and deleted_at is null), 0),
    now(), now(), null
  );
  insert into public.catalog_changes (id, entity_type, entity_id, action, field, old_value, new_value, changed_at, source)
  values (gen_random_uuid(), 'product', p_id, 'create', null, null, clean, now(), 'mobile');
end;
$$;

create function public.menu_delete_product(p_product uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current public.products%rowtype;
begin
  perform private.require_partner();
  select * into current from public.products where id = p_product and deleted_at is null for update;
  if not found then
    raise exception 'Ürün bulunamadı.' using errcode = 'P0002';
  end if;
  update public.products set deleted_at = now(), updated_at = now() where id = p_product;
  insert into public.catalog_changes (id, entity_type, entity_id, action, field, old_value, new_value, changed_at, source)
  values (gen_random_uuid(), 'product', p_product, 'delete', null, current.name, null, now(), 'mobile');
end;
$$;

revoke all on function public.menu_set_price(uuid, integer) from public, anon;
revoke all on function public.menu_add_product(uuid, uuid, text, integer) from public, anon;
revoke all on function public.menu_delete_product(uuid) from public, anon;
grant execute on function public.menu_set_price(uuid, integer) to authenticated;
grant execute on function public.menu_add_product(uuid, uuid, text, integer) to authenticated;
grant execute on function public.menu_delete_product(uuid) to authenticated;

-- ===== 20261030000009_hearth_shape.sql =====
-- Crumble salonu (2026-10-30): the table in front of the fireplace is drawn as
-- a half circle with a fire mark. New table shape 'hearth'.
alter table public.tables drop constraint tables_shape_check;
alter table public.tables add constraint tables_shape_check
  check (shape in ('circle', 'square', 'rectangle', 'rounded_rectangle', 'hearth'));

-- Floor plans and tables: the newest change wins, like products. A new POS
-- starts with the Crumble floor plan under fixed ids and an old timestamp; if
-- it pushes that copy before a restore, an edited cloud copy is kept.
create trigger floor_plans_last_writer_wins before update on public.floor_plans
  for each row execute function private.products_last_writer_wins();
create trigger tables_last_writer_wins before update on public.tables
  for each row execute function private.products_last_writer_wins();

-- ===== 20261102000010_shift_reopen.sql =====
-- Günde tek vardiya (2026-11-02): the POS does not open a second shift on the
-- same day; it continues the day's closed shift instead. That shift's closing
-- fields go back to empty. Allowed only while no later shift exists; any
-- other change to a closed shift is still refused.
create or replace function private.guard_shift_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if to_jsonb(new) = to_jsonb(old) then
    return new;
  end if;
  if old.closed_at is not null and not (
    new.closed_at is null
    and not exists (select 1 from public.shifts s where s.id <> old.id and s.opened_at >= old.opened_at)
  ) then
    raise exception 'Kapanmış vardiya değiştirilemez (shift %).', old.id
      using errcode = 'restrict_violation';
  end if;
  if not private.changes_only(to_jsonb(old), to_jsonb(new), array[
    'closed_at', 'counted_cash', 'expected_cash', 'cash_difference', 'notes', 'updated_at'
  ]) then
    raise exception 'Vardiyada sadece kapanış alanları değiştirilebilir (shift %).', old.id
      using errcode = 'restrict_violation';
  end if;
  return new;
end;
$$;

-- ===== 20261103000011_push_notifications.sql =====
-- Telefona bildirim (2026-11-03): the partners' phones get a push when the day
-- opens, at gün sonu, and when today's takings pass the last 30 days' daily
-- average or the month's best day. Sent from the database (pg_net -> Expo push
-- service), so there is no server code to deploy. At most one of each kind a
-- day ("abartmadan"); gün sonu goes again only after a reopened shift closes.
--
-- Takings follow the reports (packages/shared/src/reports): payments − refunds
-- of the shifts opened that Istanbul day.
--
-- Sending never blocks the POS: every failure is swallowed with a warning, so
-- a sync upsert never fails because of a notification.

-- pg_net ships with Supabase (Database -> Extensions); it lives in schema net.
do $$
begin
  if not exists (select 1 from pg_namespace where nspname = 'net') then
    create extension pg_net;
  end if;
end;
$$;

-- Expo push tokens of the partners' phones. Written only through
-- set_push_token(); nobody reads it over the API.
create table public.push_tokens (
  token text primary key,
  user_id uuid not null references auth.users (id),
  enabled boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.push_tokens enable row level security;
revoke all on public.push_tokens from anon, authenticated;

-- What was sent. (kind, day) keeps the once-a-day kinds once a day.
create table public.push_log (
  id bigint generated always as identity primary key,
  kind text not null check (kind in ('day_open', 'day_end', 'above_average', 'month_record')),
  day date not null,
  title text not null,
  body text not null,
  recipients integer not null,
  sent_at timestamptz not null default now()
);
create unique index push_log_once_a_day_idx on public.push_log (kind, day) where kind <> 'day_end';
alter table public.push_log enable row level security;
revoke all on public.push_log from anon, authenticated;
create policy push_log_partner_read on public.push_log for select to authenticated using (private.is_partner());
grant select on public.push_log to authenticated;

-- Phone registers (or turns off) its token. Only partners.
create function public.set_push_token(p_token text, p_enabled boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.is_partner() then
    raise exception 'Sadece ortaklar bildirim alabilir.' using errcode = '42501';
  end if;
  if p_token is null or p_token !~ '^Expo(nent)?PushToken\[[^\]]+\]$' then
    raise exception 'Geçersiz bildirim anahtarı.' using errcode = '22023';
  end if;
  insert into public.push_tokens (token, user_id, enabled)
  values (p_token, auth.uid(), coalesce(p_enabled, true))
  on conflict (token) do update
    set enabled = excluded.enabled, user_id = excluded.user_id, updated_at = now();
end;
$$;
revoke all on function public.set_push_token(text, boolean) from public, anon;
grant execute on function public.set_push_token(text, boolean) to authenticated;

-- "Now" in Istanbul. The setting lets the database tests pick a day.
create function private.istanbul_now()
returns timestamp
language sql
stable
set search_path = ''
as $$
  select coalesce(nullif(current_setting('crumble.test_now', true), '')::timestamptz, now()) at time zone 'Europe/Istanbul';
$$;

create function private.istanbul_day(t timestamptz)
returns date
language sql
immutable
set search_path = ''
as $$
  select (t at time zone 'Europe/Istanbul')::date;
$$;

-- 12340,5 TL -> '12.340,50 ₺' (formatTL).
create function private.format_tl(kurus bigint)
returns text
language sql
immutable
set search_path = ''
as $$
  select translate(to_char(kurus / 100.0, 'FM999,999,990.00'), ',.', '.,') || ' ₺';
$$;

-- Takings of the shifts opened on that Istanbul day.
create function private.day_revenue(p_day date)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select sum(p.amount) from public.payments p join public.shifts s on s.id = p.shift_id
                   where private.istanbul_day(s.opened_at) = p_day), 0)
       - coalesce((select sum(r.amount) from public.refunds r join public.shifts s on s.id = r.shift_id
                   where private.istanbul_day(s.opened_at) = p_day), 0);
$$;

-- Sends one push to every enabled phone and logs it. Returns false when a
-- once-a-day kind was already sent today. Errors are swallowed.
create function private.push(p_kind text, p_day date, p_title text, p_body text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  messages jsonb;
  n integer;
begin
  select jsonb_agg(jsonb_build_object('to', token, 'title', p_title, 'body', p_body, 'sound', 'default')), count(*)
    into messages, n
    from public.push_tokens where enabled;
  insert into public.push_log (kind, day, title, body, recipients)
  values (p_kind, p_day, p_title, p_body, n)
  on conflict do nothing;
  if not found then
    return false;
  end if;
  if n > 0 then
    perform net.http_post(
      url := 'https://exp.host/--/api/v2/push/send',
      body := messages,
      headers := '{"Content-Type": "application/json", "Accept": "application/json"}'::jsonb
    );
  end if;
  return true;
exception when others then
  raise warning 'push % failed: %', p_kind, sqlerrm;
  return false;
end;
$$;

-- Gün açıldı / gün sonu. Rows that reach the cloud late (the POS was offline)
-- are not announced: only an open/close of the last two hours.
create function private.notify_shift()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  now_ist timestamp := private.istanbul_now();
  v_day date := private.istanbul_day(new.opened_at);
  revenue bigint;
  cash bigint;
  sales integer;
begin
  if tg_op = 'INSERT' and new.closed_at is null then
    if new.opened_at at time zone 'Europe/Istanbul' > now_ist - interval '2 hours' then
      perform private.push('day_open', v_day, 'Gün açıldı',
        'Vardiya açıldı · ' || to_char(new.opened_at at time zone 'Europe/Istanbul', 'HH24:MI'));
    end if;
  elsif new.closed_at is not null and (tg_op = 'INSERT' or old.closed_at is null) then
    if new.closed_at at time zone 'Europe/Istanbul' > now_ist - interval '2 hours' then
      revenue := private.day_revenue(v_day);
      cash := coalesce((select sum(amount) from public.payments where shift_id = new.id and method = 'cash'), 0)
            - coalesce((select sum(amount) from public.refunds where shift_id = new.id and method = 'cash'), 0);
      select count(*) into sales from public.tabs where closed_shift_id = new.id and status = 'paid';
      perform private.push('day_end', v_day, 'Gün sonu',
        'Ciro ' || private.format_tl(revenue) || ' · ' || sales || ' satış · kasada nakit ' || private.format_tl(cash) || '.');
    end if;
  end if;
  return null;
exception when others then
  raise warning 'notify_shift failed: %', sqlerrm;
  return null;
end;
$$;

create trigger shifts_notify after insert or update of closed_at on public.shifts
  for each row execute function private.notify_shift();

-- After each payment of today: past the 30-day average (at least 5 open days
-- behind it) or the month's best day (at least 3 earlier days this month).
-- A new month record also counts as "above average", so that one is not sent
-- separately afterwards.
create function private.notify_revenue()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  now_ist timestamp := private.istanbul_now();
  v_day date;
  revenue bigint;
  avg_revenue numeric;
  avg_days integer;
  best bigint;
  best_days integer;
begin
  select private.istanbul_day(s.opened_at) into v_day from public.shifts s where s.id = new.shift_id;
  if v_day is distinct from now_ist::date then
    return null;
  end if;
  if (select count(*) from public.push_log l where l.day = v_day
        and l.kind in ('above_average', 'month_record')) = 2 then
    return null;
  end if;
  revenue := private.day_revenue(v_day);

  select max(r), count(*) into best, best_days from (
    select private.day_revenue(d) as r
    from (select distinct private.istanbul_day(opened_at) as d from public.shifts) days
    where d >= date_trunc('month', v_day)::date and d < v_day
  ) month_days;
  if best_days >= 3 and revenue > best then
    if private.push('month_record', v_day, 'Bu ayın rekoru',
        'Bugünkü ciro ' || private.format_tl(revenue) || ', ayın en iyi günü (önceki en iyi ' || private.format_tl(best) || ').') then
      insert into public.push_log (kind, day, title, body, recipients)
      values ('above_average', v_day, '(ay rekoru ile birlikte)', '', 0)
      on conflict do nothing;
      return null;
    end if;
  end if;

  select avg(r), count(*) into avg_revenue, avg_days from (
    select private.day_revenue(d) as r
    from (select distinct private.istanbul_day(opened_at) as d from public.shifts) days
    where d >= v_day - 30 and d < v_day
  ) last_days;
  if avg_days >= 5 and revenue > avg_revenue then
    perform private.push('above_average', v_day, 'Ortalamanın üstündeyiz',
      'Bugünkü ciro ' || private.format_tl(revenue) || ', son 30 günün günlük ortalaması ' || private.format_tl(round(avg_revenue)::bigint) || '.');
  end if;
  return null;
exception when others then
  raise warning 'notify_revenue failed: %', sqlerrm;
  return null;
end;
$$;

create trigger payments_notify after insert on public.payments
  for each row execute function private.notify_revenue();

-- ===== 20261104000012_tab_requests.sql =====
-- Açık hesaplar telefondan (2026-11-04): a partner may take a payment (amount
-- + cash/card), rename a named tab or cancel a tab that took no money. The
-- phone does not write tabs or payments: it leaves a request here, the POS
-- pulls it, applies it with its own rules (into its open shift) and syncs the
-- result as usual, then marks the request done or rejected. So the POS stays
-- the only writer of sales ("kasa doğrudur") and both sides never edit the
-- same tab at once.

create table public.tab_requests (
  id uuid primary key,
  tab_id uuid not null references public.tabs (id),
  kind text not null check (kind in ('pay', 'rename', 'void')),
  amount integer check (amount > 0),
  method text check (method in ('cash', 'card')),
  customer_name text check (customer_name is null or btrim(customer_name) <> ''),
  status text not null default 'pending' check (status in ('pending', 'done', 'rejected')),
  error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint tab_requests_kind_fields check (
    (kind = 'pay' and amount is not null and method is not null and customer_name is null)
    or (kind = 'rename' and customer_name is not null and amount is null and method is null)
    or (kind = 'void' and amount is null and method is null and customer_name is null)
  )
);

create index tab_requests_pending_idx on public.tab_requests (created_at) where status = 'pending';

alter table public.tab_requests enable row level security;
revoke all on public.tab_requests from anon;
revoke insert, update, delete, truncate on public.tab_requests from authenticated;
create policy tab_requests_select on public.tab_requests
  for select to authenticated using (private.is_device() or private.is_partner());
grant select on public.tab_requests to authenticated;

-- Phone: leave a request. The id comes from the phone, so a retried call is harmless.
create function public.tab_request(
  p_id uuid, p_tab uuid, p_kind text, p_amount integer default null, p_method text default null, p_name text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  current public.tabs%rowtype;
begin
  if not private.is_partner() then
    raise exception 'Sadece ortaklar açık hesap işlemi yapabilir.' using errcode = '42501';
  end if;
  select * into current from public.tabs where id = p_tab;
  if not found then
    raise exception 'Hesap bulunamadı.' using errcode = 'P0002';
  end if;
  if current.status <> 'open' then
    raise exception 'Hesap kapanmış.' using errcode = '22023';
  end if;
  if p_kind = 'pay' and (p_amount is null or p_amount <= 0 or p_method not in ('cash', 'card')) then
    raise exception 'Tutar ve ödeme yöntemi gerekli.' using errcode = '22023';
  end if;
  if p_kind = 'rename' and (p_name is null or btrim(p_name) = '') then
    raise exception 'Hesap adı boş olamaz.' using errcode = '22023';
  end if;
  insert into public.tab_requests (id, tab_id, kind, amount, method, customer_name)
  values (
    p_id, p_tab, p_kind,
    case when p_kind = 'pay' then p_amount end,
    case when p_kind = 'pay' then p_method end,
    case when p_kind = 'rename' then btrim(p_name) end
  )
  on conflict (id) do nothing;
end;
$$;
revoke all on function public.tab_request(uuid, uuid, text, integer, text, text) from public, anon;
grant execute on function public.tab_request(uuid, uuid, text, integer, text, text) to authenticated;

-- POS: report what happened to a request. A finished request does not change again.
create function public.tab_request_result(p_id uuid, p_ok boolean, p_error text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.is_device() then
    raise exception 'Sadece kasa istek sonucunu yazabilir.' using errcode = '42501';
  end if;
  update public.tab_requests
  set status = case when p_ok then 'done' else 'rejected' end,
      error = case when p_ok then null else p_error end,
      updated_at = now()
  where id = p_id and status = 'pending';
end;
$$;
revoke all on function public.tab_request_result(uuid, boolean, text) from public, anon;
grant execute on function public.tab_request_result(uuid, boolean, text) to authenticated;

-- The phone sees requests turn done/rejected and lines being added without waiting for its poll.
alter publication supabase_realtime add table public.tab_requests, public.tab_items;

-- ===== 20261104000013_day_end_once.sql =====
-- Gün sonu once per result (2026-11-04): the partners got four identical
-- "Gün sonu" pushes in two minutes after the day was reopened ("Bugünün
-- vardiyasına devam et") and closed again without a new sale. A day end is now
-- sent again only when its numbers differ from one already sent for that day.

create or replace function private.notify_shift()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  now_ist timestamp := private.istanbul_now();
  v_day date := private.istanbul_day(new.opened_at);
  revenue bigint;
  cash bigint;
  sales integer;
  v_body text;
begin
  if tg_op = 'INSERT' and new.closed_at is null then
    if new.opened_at at time zone 'Europe/Istanbul' > now_ist - interval '2 hours' then
      perform private.push('day_open', v_day, 'Gün açıldı',
        'Vardiya açıldı · ' || to_char(new.opened_at at time zone 'Europe/Istanbul', 'HH24:MI'));
    end if;
  elsif new.closed_at is not null and (tg_op = 'INSERT' or old.closed_at is null) then
    if new.closed_at at time zone 'Europe/Istanbul' > now_ist - interval '2 hours' then
      revenue := private.day_revenue(v_day);
      cash := coalesce((select sum(amount) from public.payments where shift_id = new.id and method = 'cash'), 0)
            - coalesce((select sum(amount) from public.refunds where shift_id = new.id and method = 'cash'), 0);
      select count(*) into sales from public.tabs where closed_shift_id = new.id and status = 'paid';
      v_body := 'Ciro ' || private.format_tl(revenue) || ' · ' || sales || ' satış · kasada nakit ' || private.format_tl(cash) || '.';
      -- Reopened and closed again with nothing new: the phone already has it.
      if not exists (select 1 from public.push_log l where l.kind = 'day_end' and l.day = v_day and l.body = v_body) then
        perform private.push('day_end', v_day, 'Gün sonu', v_body);
      end if;
    end if;
  end if;
  return null;
exception when others then
  raise warning 'notify_shift failed: %', sqlerrm;
  return null;
end;
$$;

commit;
